import semver

# Check R1: Immutability
vi = semver.parse("1.2.3")
print("=== R1: Immutability ===")
try:
    vi.major = 2
    print("ERROR: major should be immutable!")
except AttributeError:
    print("OK: major is immutable")

try:
    vi.minor = 2
    print("ERROR: minor should be immutable!")
except AttributeError:
    print("OK: minor is immutable")

# Check R2: Iteration
print("\n=== R2: Iteration ===")
try:
    items = list(vi)
    print(f"Items: {items}")
except TypeError as e:
    print(f"NOT ITERABLE: {e}")

# Check R3: Comparison with tuple
print("\n=== R3: Comparison ===")
try:
    result = vi > (1, 0, 0)
    print(f"vi > (1,0,0) = {result}")
except TypeError as e:
    print(f"Error comparing with tuple: {e}")

try:
    result = vi > "1.0.0"
    print(f"vi > '1.0.0' = {result}")
except TypeError as e:
    print(f"Correctly disallowed comparison with string: {e}")

try:
    result = vi > 1
    print(f"vi > 1 = {result}")
except TypeError as e:
    print(f"Correctly disallowed comparison with int: {e}")
